<script setup>
import {useForm,Link} from '@inertiajs/vue3';import AppLayout from '../../Layouts/AppLayout.vue';const form=useForm({email:'',password:'',remember:false});const submit=()=>form.post('/login');
</script>
<template><AppLayout><div class="auth-wrap"><div class="auth-card"><h1>Selamat datang 👋</h1><p class="muted">Masuk untuk melanjutkan belanja.</p><form @submit.prevent="submit"><div class="field"><label>Email</label><input type="email" v-model="form.email" required><small style="color:#dc3545">{{form.errors.email}}</small></div><div class="field"><label>Password</label><input type="password" v-model="form.password" required></div><label class="row"><input type="checkbox" v-model="form.remember"> Ingat saya</label><button class="btn" style="width:100%;margin-top:18px" :disabled="form.processing">Masuk</button></form><p class="muted">Belum punya akun? <Link href="/register" style="color:#2457d6">Daftar sekarang</Link></p></div></div></AppLayout></template>
